let seeded = false;
async function seedOnce(env) {
  if (seeded || !SEED.length || (env.DEV && !env.SEED_LOCAL)) return;
  try {
    if (await env.DB.prepare("SELECT v FROM meta WHERE k = ?1").bind(SEED_KEY).first()) { seeded = true; return; }
    const ids = SEED.map((x) => x[0]);
    const have = new Set(((await env.DB.prepare("SELECT id FROM docs WHERE coll = 'leads' AND id IN (SELECT value FROM json_each(?1))").bind(JSON.stringify(ids)).all()).results || []).map((r) => r.id));
    const top = await env.DB.prepare("SELECT COALESCE(MAX(CAST(json_extract(data, '$.order') AS INTEGER)), 0) AS m FROM docs WHERE coll = 'leads'").first();
    let o = Number(top && top.m) || 0; const now = Date.now(), st = [];
    for (const [id, d] of SEED) {
      if (have.has(id)) continue;
      o++; st.push(env.DB.prepare("INSERT INTO docs (coll, id, data, updated) VALUES ('leads', ?1, ?2, ?3) ON CONFLICT(coll, id) DO NOTHING").bind(id, JSON.stringify(Object.assign({}, d, { order: o })), now));
    }
    st.push(env.DB.prepare("INSERT INTO meta (k, v) VALUES (?1, ?2) ON CONFLICT(k) DO NOTHING").bind(SEED_KEY, String(st.length)));
    st.push(env.DB.prepare("INSERT INTO meta (k, v) VALUES ('crm_rev', '1') ON CONFLICT(k) DO UPDATE SET v = CAST(CAST(v AS INTEGER) + 1 AS TEXT)"));
    await env.DB.batch(st);
    seeded = true;
  } catch (e) { /* the admin keeps working; it is tried again on the next request */ }
}

/* ---------- v21: notifications on Chris's phone (Web Push to the 404 CRM app on his home screen) ----------
   Standard Web Push: VAPID (RFC 8292) to say who sends, and the message encrypted for each device (RFC 8291, aes128gcm), so the
   push service (Apple, Google, Mozilla) only carries it. The VAPID key pair is made the first time and its private half is sealed
   with KIT_KEY like the other secrets; without KIT_KEY it is kept as is in meta (the database is ours alone). */
const VAPID_SUB = "mailto:hola@404growth.com";
const cat = (...a) => { const n = a.reduce((s, x) => s + x.length, 0), o = new Uint8Array(n); let i = 0; for (const x of a) { o.set(x, i); i += x.length; } return o; };
async function hkdf(salt, ikm, info, len) {
  const k = await crypto.subtle.importKey("raw", ikm, "HKDF", false, ["deriveBits"]);
  return new Uint8Array(await crypto.subtle.deriveBits({ name: "HKDF", hash: "SHA-256", salt: salt, info: info }, k, len * 8));
}
async function vapidKeys(env) {
  let raw = await getMeta(env, "vapid");
  if (raw) {
    let j = null;
    if (raw.startsWith("v1.")) { const t = await unseal(env, raw, "vapid"); j = t ? JSON.parse(t) : null; } else { try { j = JSON.parse(raw); } catch (e) {} }
    if (j && j.pub && j.jwk) return j;
  }
  const kp = await crypto.subtle.generateKey({ name: "ECDSA", namedCurve: "P-256" }, true, ["sign", "verify"]);
  const jwk = await crypto.subtle.exportKey("jwk", kp.privateKey);
  const pub = b64(new Uint8Array(await crypto.subtle.exportKey("raw", kp.publicKey)));
  const j = { pub: pub, jwk: jwk }, s = await seal(env, JSON.stringify(j), "vapid");
  await setMeta(env, "vapid", s || JSON.stringify(j));
  return j;
}
async function vapidAuth(env, endpoint) {
  const K = await vapidKeys(env), aud = new URL(endpoint).origin;
  const h = b64(enc.encode(JSON.stringify({ typ: "JWT", alg: "ES256" })));
  const c = b64(enc.encode(JSON.stringify({ aud: aud, exp: Math.floor(Date.now() / 1000) + 12 * 3600, sub: VAPID_SUB })));
  const key = await crypto.subtle.importKey("jwk", K.jwk, { name: "ECDSA", namedCurve: "P-256" }, false, ["sign"]);
  const sig = new Uint8Array(await crypto.subtle.sign({ name: "ECDSA", hash: "SHA-256" }, key, enc.encode(h + "." + c)));
  return "vapid t=" + h + "." + c + "." + b64(sig) + ", k=" + K.pub;
}
// RFC 8291: the message for one device, encrypted with its public key (p256dh) and its secret (auth)
async function pushBody(p256dh, auth, text) {
  const ua = unb64(p256dh), sec = unb64(auth);
  const as = await crypto.subtle.generateKey({ name: "ECDH", namedCurve: "P-256" }, true, ["deriveBits"]);
  const asPub = new Uint8Array(await crypto.subtle.exportKey("raw", as.publicKey));
  const uaKey = await crypto.subtle.importKey("raw", ua, { name: "ECDH", namedCurve: "P-256" }, false, []);
  const shared = new Uint8Array(await crypto.subtle.deriveBits({ name: "ECDH", public: uaKey }, as.privateKey, 256));
  const ikm = await hkdf(sec, shared, cat(enc.encode("WebPush: info\0"), ua, asPub), 32);
  const salt = rand(16);
  const cek = await hkdf(salt, ikm, enc.encode("Content-Encoding: aes128gcm\0"), 16);
  const nonce = await hkdf(salt, ikm, enc.encode("Content-Encoding: nonce\0"), 12);
  const k = await crypto.subtle.importKey("raw", cek, "AES-GCM", false, ["encrypt"]);
  const ct = new Uint8Array(await crypto.subtle.encrypt({ name: "AES-GCM", iv: nonce }, k, cat(enc.encode(text), new Uint8Array([2]))));
  const rs = new Uint8Array([0, 0, 16, 0]);   // record size 4096
  return cat(salt, rs, new Uint8Array([asPub.length]), asPub, ct);
}
// one message to every device that asked for them; a device the push service no longer knows (404 / 410) is forgotten
async function pushAll(env, msg) {
  const subs = (await env.DB.prepare("SELECT ep, p256dh, auth FROM push").all()).results || [];
  const text = JSON.stringify(msg).slice(0, 3000), out = [];
  for (const s of subs) {
    let st = 0;
    try {
      const r = await fetch(s.ep, { method: "POST", headers: { "content-type": "application/octet-stream", "content-encoding": "aes128gcm", ttl: "86400", urgency: "high",
        authorization: await vapidAuth(env, s.ep) }, body: await pushBody(s.p256dh, s.auth, text) });
      st = r.status;
    } catch (e) { st = -1; }
    out.push(st);
    if (st === 404 || st === 410) await env.DB.prepare("DELETE FROM push WHERE ep = ?1").bind(s.ep).run();
    else if (st >= 200 && st < 300) await env.DB.prepare("UPDATE push SET ok = ?1, fails = 0 WHERE ep = ?2").bind(Date.now(), s.ep).run();
    else await env.DB.prepare("UPDATE push SET fails = fails + 1 WHERE ep = ?1").bind(s.ep).run();
  }
  return out;
}
